import { type Artifact, type ArtifactVersion, formatBytes } from '@artifact-hub/shared';
import {
  BuildingIcon,
  DownloadIcon,
  LockIcon,
  MaximizeIcon,
  Share2Icon,
  UploadIcon,
} from 'lucide-react';
import { useRef } from 'react';
import { Link, useNavigate, useParams, useSearchParams } from 'react-router';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';
import { Badge } from '@/components/ui/badge.tsx';
import { Button } from '@/components/ui/button.tsx';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs.tsx';
import { ArtifactDetails } from '@/features/artifacts/artifact-details.tsx';
import { typeLabel } from '@/features/artifacts/artifact-types.ts';
import { artifactContentPath, artifactContentUrl } from '@/features/artifacts/artifacts-api.ts';
import { NewVersionDialog } from '@/features/artifacts/new-version-dialog.tsx';
import { useArtifact, useArtifactVersions } from '@/features/artifacts/use-artifacts.ts';
import { VersionList } from '@/features/artifacts/version-list.tsx';
import { ArtifactViewer } from '@/features/artifacts/viewers/artifact-viewer.tsx';
import { ShareDialog } from '@/features/sharing/share-dialog.tsx';
import { isApiError } from '@/lib/api/api-error.ts';
import { formatRelativeTime } from '@/lib/format.ts';

const VERSION_PARAM = /^[1-9]\d{0,8}$/;

export function ArtifactPage() {
  const { id = '' } = useParams();
  const { data: artifact, error, refetch } = useArtifact(id);

  if (isApiError(error, 'NOT_FOUND')) return <ArtifactNotFound />;
  if (error) {
    return (
      <div className="h-[60vh]">
        <InlineError error={error} onRetry={() => void refetch()} />
      </div>
    );
  }
  if (!artifact) {
    return (
      <div className="h-[60vh]">
        <InlineLoading />
      </div>
    );
  }
  return <ArtifactView artifact={artifact} />;
}

/**
 * The version picked with `?v=N`, or the current one. `undefined` while the version list
 * loads, `null` if there's no such version.
 */
function useSelectedVersion(artifact: Artifact): ArtifactVersion | null | undefined {
  const [searchParams] = useSearchParams();
  const param = searchParams.get('v');
  const current = artifact.currentVersion;
  const requested = param !== null && VERSION_PARAM.test(param) ? Number(param) : null;
  const wantsOther = param !== null && requested !== current?.versionNo;
  const { data: versions, error } = useArtifactVersions(artifact.id, { enabled: wantsOther });

  if (!wantsOther) return current;
  if (requested === null || error) return null;
  return versions ? (versions.find((v) => v.versionNo === requested) ?? null) : undefined;
}

function ArtifactView({ artifact }: { artifact: Artifact }) {
  const viewerRef = useRef<HTMLDivElement>(null);
  const navigate = useNavigate();
  const { permissions } = artifact;
  const current = artifact.currentVersion;
  const version = useSelectedVersion(artifact);

  return (
    <article className="grid gap-6">
      <header className="flex flex-wrap items-start justify-between gap-4">
        <div className="grid min-w-0 gap-1.5">
          <h1 className="text-2xl font-semibold tracking-tight break-words">{artifact.title}</h1>
          <p className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm text-muted-foreground">
            <span>{artifact.owner.displayName}</span>
            {version ? (
              <>
                <span aria-hidden="true">·</span>
                <span>v{version.versionNo}</span>
                <span aria-hidden="true">·</span>
                <span>
                  {typeLabel(version.mimeType)}, {formatBytes(version.sizeBytes)}
                </span>
              </>
            ) : null}
            <span aria-hidden="true">·</span>
            <time
              dateTime={artifact.updatedAt}
              title={new Date(artifact.updatedAt).toLocaleString()}
            >
              Updated {formatRelativeTime(artifact.updatedAt)}
            </time>
            {artifact.visibility === 'private' ? (
              <Badge variant="secondary">
                <LockIcon aria-hidden="true" />
                Private
              </Badge>
            ) : (
              <Badge variant="secondary">
                <BuildingIcon aria-hidden="true" />
                Company
              </Badge>
            )}
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          {permissions.share ? (
            <ShareDialog artifact={artifact}>
              <Button variant="outline">
                <Share2Icon aria-hidden="true" />
                Share
              </Button>
            </ShareDialog>
          ) : null}
          {permissions.edit ? (
            <NewVersionDialog
              artifact={artifact}
              // Show the new version, wherever the page was.
              onPublished={() => void navigate(`/artifacts/${artifact.id}`)}
            >
              <Button variant="outline">
                <UploadIcon aria-hidden="true" />
                Upload new version
              </Button>
            </NewVersionDialog>
          ) : null}
          {version ? (
            <>
              {document.fullscreenEnabled ? (
                <Button
                  variant="outline"
                  onClick={() => void viewerRef.current?.requestFullscreen()}
                >
                  <MaximizeIcon aria-hidden="true" />
                  Full screen
                </Button>
              ) : null}
              <Button asChild variant="outline">
                <a href={artifactContentUrl(artifact.id, version.versionNo, { download: true })}>
                  <DownloadIcon aria-hidden="true" />
                  Download
                </a>
              </Button>
            </>
          ) : null}
        </div>
      </header>

      {version && current && version.versionNo !== current.versionNo ? (
        <p
          role="status"
          className="rounded-md border bg-muted px-3 py-2 text-sm text-muted-foreground"
        >
          You're viewing v{version.versionNo}, an earlier version.{' '}
          <Link to={`/artifacts/${artifact.id}`} className="font-medium text-foreground underline">
            Show the latest (v{current.versionNo})
          </Link>
        </p>
      ) : null}

      <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_20rem]">
        <div
          ref={viewerRef}
          className="h-[75vh] overflow-hidden rounded-xl border bg-background [&:fullscreen]:h-screen [&:fullscreen]:rounded-none [&:fullscreen]:border-0"
        >
          {version ? (
            <ArtifactViewer
              title={artifact.title}
              version={version}
              contentPath={artifactContentPath(artifact.id, version.versionNo)}
            />
          ) : version === undefined ? (
            <InlineLoading />
          ) : current ? (
            <InlineError error="This version doesn't exist." />
          ) : (
            <InlineError error="This artifact is waiting for its first upload." />
          )}
        </div>

        <aside>
          <Tabs defaultValue="details">
            <TabsList className="w-full">
              <TabsTrigger value="details">Details</TabsTrigger>
              <TabsTrigger value="versions">Versions</TabsTrigger>
            </TabsList>
            <TabsContent value="details" className="pt-2">
              <ArtifactDetails artifact={artifact} />
            </TabsContent>
            <TabsContent value="versions" className="pt-2">
              {current ? (
                <VersionList
                  artifactId={artifact.id}
                  currentVersionNo={current.versionNo}
                  selectedVersionNo={version?.versionNo ?? current.versionNo}
                />
              ) : (
                <p className="text-sm text-muted-foreground">No versions yet.</p>
              )}
            </TabsContent>
          </Tabs>
        </aside>
      </div>
    </article>
  );
}

function ArtifactNotFound() {
  return (
    <section className="flex flex-col items-center gap-4 py-24 text-center">
      <h1 className="text-2xl font-semibold tracking-tight">Artifact not found</h1>
      <p className="max-w-md text-muted-foreground">
        It doesn't exist, or it hasn't been shared with you.
      </p>
      <Button asChild variant="outline">
        <Link to="/">Go home</Link>
      </Button>
    </section>
  );
}
import {
  type Artifact,
  type ArtifactListResponse,
  type ArtifactListScope,
  type ArtifactTagListResponse,
  artifactTagListResponseSchema,
  type ArtifactVersion,
  artifactListResponseSchema,
  artifactResponseSchema,
  artifactVersionListResponseSchema,
  type CreateArtifactRequest,
  type CreateVersionRequest,
  type UpdateArtifactRequest,
} from '@artifact-hub/shared';
import { apiFetchContent, apiRequest } from '@/lib/api/client.ts';
import type { ArtifactListParams } from './artifacts.types.ts';

/**
 * One artifact: `['artifact', id]`, its versions under it (invalidating the artifact refreshes
 * both). Lists: `['artifacts', params]`, invalidated together.
 */
export const artifactQueryKey = (id: string) => ['artifact', id] as const;
export const artifactVersionsQueryKey = (id: string) =>
  [...artifactQueryKey(id), 'versions'] as const;
export const artifactListsQueryKey = ['artifacts'] as const;
export const artifactListQueryKey = (params: ArtifactListParams) =>
  [...artifactListsQueryKey, params] as const;

export async function fetchArtifacts(
  { scope, page, pageSize, q, type, tag }: ArtifactListParams,
  signal?: AbortSignal,
): Promise<ArtifactListResponse> {
  const query = new URLSearchParams({ scope, page: String(page), pageSize: String(pageSize) });
  for (const [key, value] of Object.entries({ q, type, tag })) {
    if (value) query.set(key, value);
  }
  return apiRequest(`/artifacts?${query}`, { schema: artifactListResponseSchema, signal });
}

export const artifactTagsQueryKey = (scope: ArtifactListScope) =>
  [...artifactListsQueryKey, 'tags', scope] as const;

/** The tags used in a gallery scope, the most used first. */
export async function fetchArtifactTags(
  scope: ArtifactListScope,
  signal?: AbortSignal,
): Promise<ArtifactTagListResponse['items']> {
  const query = new URLSearchParams({ scope });
  return (
    await apiRequest(`/artifacts/tags?${query}`, { schema: artifactTagListResponseSchema, signal })
  ).items;
}

/** Multipart upload: the metadata first, then the file (the server reads them in that order). */
export async function publishArtifact(
  file: File,
  metadata: CreateArtifactRequest,
): Promise<Artifact> {
  const form = new FormData();
  form.append('metadata', JSON.stringify(metadata));
  form.append('file', file);
  return (
    await apiRequest('/artifacts', { method: 'POST', body: form, schema: artifactResponseSchema })
  ).artifact;
}

export async function fetchArtifact(id: string, signal?: AbortSignal): Promise<Artifact> {
  return (
    await apiRequest(artifactPath(id), {
      schema: artifactResponseSchema,
      signal,
    })
  ).artifact;
}

const artifactPath = (id: string) => `/artifacts/${encodeURIComponent(id)}`;

/** Multipart, like publishing: the details first, then the file. Returns the updated artifact. */
export async function publishVersion(
  id: string,
  file: File,
  metadata: CreateVersionRequest,
): Promise<Artifact> {
  const form = new FormData();
  form.append('metadata', JSON.stringify(metadata));
  form.append('file', file);
  return (
    await apiRequest(`${artifactPath(id)}/versions`, {
      method: 'POST',
      body: form,
      schema: artifactResponseSchema,
    })
  ).artifact;
}

/** Every version, newest first. */
export async function fetchArtifactVersions(
  id: string,
  signal?: AbortSignal,
): Promise<ArtifactVersion[]> {
  return (
    await apiRequest(`${artifactPath(id)}/versions`, {
      schema: artifactVersionListResponseSchema,
      signal,
    })
  ).items;
}

export async function updateArtifact(
  id: string,
  changes: UpdateArtifactRequest,
): Promise<Artifact> {
  return (
    await apiRequest(artifactPath(id), {
      method: 'PATCH',
      body: changes,
      schema: artifactResponseSchema,
    })
  ).artifact;
}

export async function deleteArtifact(id: string): Promise<void> {
  await apiRequest(artifactPath(id), { method: 'DELETE' });
}

/** Where a version's bytes are, relative to `/api`. */
export function artifactContentPath(artifactId: string, versionNo: number): string {
  return `${artifactPath(artifactId)}/versions/${versionNo}/content`;
}

/** URL of a version's bytes, for `<img>`, `<iframe>` and download links. */
export function artifactContentUrl(
  artifactId: string,
  versionNo: number,
  { download = false } = {},
): string {
  return `/api${artifactContentPath(artifactId, versionNo)}${download ? '?download=1' : ''}`;
}

/** Content (at a path relative to `/api`) as text, e.g. Markdown. */
export async function fetchContentText(contentPath: string, signal?: AbortSignal): Promise<string> {
  return (await apiFetchContent(contentPath, { signal })).text();
}

/** Content (at a path relative to `/api`) as bytes, e.g. a PDF. */
export async function fetchContentBytes(
  contentPath: string,
  signal?: AbortSignal,
): Promise<Uint8Array> {
  const res = await apiFetchContent(contentPath, { signal });
  return new Uint8Array(await res.arrayBuffer());
}
import type {
  Artifact,
  ArtifactListScope,
  CreateArtifactRequest,
  CreateVersionRequest,
  UpdateArtifactRequest,
} from '@artifact-hub/shared';
import { keepPreviousData, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { isApiError } from '@/lib/api/api-error.ts';
import {
  artifactListQueryKey,
  artifactListsQueryKey,
  artifactQueryKey,
  artifactTagsQueryKey,
  artifactVersionsQueryKey,
  deleteArtifact,
  fetchArtifact,
  fetchArtifacts,
  fetchArtifactTags,
  fetchArtifactVersions,
  publishArtifact,
  publishVersion,
  updateArtifact,
} from './artifacts-api.ts';
import type { ArtifactListParams } from './artifacts.types.ts';

export function useArtifact(id: string) {
  return useQuery({
    queryKey: artifactQueryKey(id),
    queryFn: ({ signal }) => fetchArtifact(id, signal),
    // A 404 won't change by asking again.
    retry: (failureCount, error) => !isApiError(error, 'NOT_FOUND') && failureCount < 2,
  });
}

export function useArtifactList(params: ArtifactListParams) {
  return useQuery({
    queryKey: artifactListQueryKey(params),
    queryFn: ({ signal }) => fetchArtifacts(params, signal),
    // Keep showing the current page while the next one loads.
    placeholderData: keepPreviousData,
  });
}

/** Invalidated with the lists, since publishing or editing changes them. */
export function useArtifactTags(scope: ArtifactListScope) {
  return useQuery({
    queryKey: artifactTagsQueryKey(scope),
    queryFn: ({ signal }) => fetchArtifactTags(scope, signal),
  });
}

export function usePublishArtifact() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ file, metadata }: { file: File; metadata: CreateArtifactRequest }) =>
      publishArtifact(file, metadata),
    onSuccess: (artifact) => {
      queryClient.setQueryData(artifactQueryKey(artifact.id), artifact);
      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
    },
  });
}

export function useArtifactVersions(id: string, { enabled = true } = {}) {
  return useQuery({
    queryKey: artifactVersionsQueryKey(id),
    queryFn: ({ signal }) => fetchArtifactVersions(id, signal),
    enabled,
  });
}

/** Caches a changed artifact and refreshes everything that shows it. */
function useArtifactChanged() {
  const queryClient = useQueryClient();
  return (artifact: Artifact) => {
    queryClient.setQueryData(artifactQueryKey(artifact.id), artifact);
    void queryClient.invalidateQueries({ queryKey: artifactVersionsQueryKey(artifact.id) });
    void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
  };
}

export function usePublishVersion(id: string) {
  const onChanged = useArtifactChanged();
  return useMutation({
    mutationFn: ({ file, metadata }: { file: File; metadata: CreateVersionRequest }) =>
      publishVersion(id, file, metadata),
    onSuccess: onChanged,
  });
}

export function useUpdateArtifact(id: string) {
  const onChanged = useArtifactChanged();
  return useMutation({
    mutationFn: (changes: UpdateArtifactRequest) => updateArtifact(id, changes),
    onSuccess: onChanged,
  });
}

/**
 * `leavePage` navigates away from the artifact; its queries are dropped only after that, so
 * the page doesn't refetch the artifact and flash "not found" on its way out.
 */
export function useDeleteArtifact(id: string, leavePage: () => void | Promise<void>) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: () => deleteArtifact(id),
    onSuccess: async () => {
      await leavePage();
      queryClient.removeQueries({ queryKey: artifactQueryKey(id) });
      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
    },
  });
}
import type { ArtifactListScope, ArtifactTypeFilter } from '@artifact-hub/shared';
import type { z } from 'zod';
import type { metadataFormSchema } from './metadata-form-schema.ts';

/** What the gallery shows: a scope, narrowed by optional filters. */
export interface GalleryFilters {
  scope: ArtifactListScope;
  /** Words to search for. */
  q?: string;
  type?: ArtifactTypeFilter;
  tag?: string;
}

export interface ArtifactListParams extends GalleryFilters {
  /** 1-based. */
  page: number;
  pageSize: number;
}

/** What the details form holds before the schema normalizes it (tags as one string). */
export type MetadataFormValues = z.input<typeof metadataFormSchema>;
/** What it submits. */
export type MetadataFormOutput = z.output<typeof metadataFormSchema>;
import { type ArtifactVersion, formatBytes } from '@artifact-hub/shared';
import { Link } from 'react-router';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';
import { Badge } from '@/components/ui/badge.tsx';
import { formatRelativeTime } from '@/lib/format.ts';
import { cn } from '@/lib/utils';
import { typeLabel } from './artifact-types.ts';
import { useArtifactVersions } from './use-artifacts.ts';

/** Every version, newest first; each links to the artifact page showing that version. */
export function VersionList({
  artifactId,
  currentVersionNo,
  selectedVersionNo,
}: {
  artifactId: string;
  currentVersionNo: number;
  selectedVersionNo: number;
}) {
  const { data: versions, error, refetch } = useArtifactVersions(artifactId);

  if (error) return <InlineError error={error} onRetry={() => void refetch()} />;
  if (!versions) return <InlineLoading />;

  return (
    <ol className="grid gap-1" aria-label="Versions">
      {versions.map((version) => (
        <li key={version.id}>
          <VersionItem
            artifactId={artifactId}
            version={version}
            current={version.versionNo === currentVersionNo}
            selected={version.versionNo === selectedVersionNo}
          />
        </li>
      ))}
    </ol>
  );
}

function VersionItem({
  artifactId,
  version,
  current,
  selected,
}: {
  artifactId: string;
  version: ArtifactVersion;
  current: boolean;
  selected: boolean;
}) {
  return (
    <Link
      // The current version has the artifact's plain URL.
      to={current ? `/artifacts/${artifactId}` : `/artifacts/${artifactId}?v=${version.versionNo}`}
