    expect(
      sharePeopleRequestSchema.parse({
        emails: [' Sara@Example.com ', 'sara@example.com', 'tom@example.com'],
        permission: 'comment',
      }),
    ).toEqual({
      emails: ['sara@example.com', 'tom@example.com'],
      permission: 'comment',
      versionNo: null,
    });
  });

  it.each([
    [{ emails: [], permission: 'view' }, 'emails'],
