import type { Comment as CommentDto } from '@artifact-hub/shared';
import {
  Column,
  CreateDateColumn,
  Entity,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { ArtifactVersion } from '../artifacts/artifact-version.entity.js';
import { User } from '../users/user.entity.js';
import type { CommentView } from './comments.types.js';

/** A comment on one version of an artifact, or a reply to one (one level deep). */
@Entity('comments')
export class Comment {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column('uuid')
  artifactId: string;

  @Column('uuid')
  versionId: string;

  @ManyToOne(() => ArtifactVersion, { onDelete: 'CASCADE' })
  @JoinColumn()
  version: ArtifactVersion;

  /** The top-level comment this replies to; null for a top-level comment. */
  @Column({ type: 'uuid', nullable: true })
  parentId: string | null;

  @Column('uuid')
  authorId: string;

