      const id = await publish(2);
      await shareWith(bob, id, 'comment');
      const posted = await comment(bob, id, { body: 'On v2' });
      await send('patch', ada, `/artifacts/${id}/access/people/${bob.id}`)
        .send({ versionNo: 1 })
