import {
  type ArtifactAccess,
  artifactAccessResponseSchema,
  type SetCompanyAccessRequest,
  type SetShareLinkRequest,
  type SharedArtifactResponse,
  sharedArtifactResponseSchema,
  type SharePeopleRequest,
  type UpdatePersonAccessRequest,
  type UserSummary,
  userSearchResponseSchema,
} from '@artifact-hub/shared';
import { artifactQueryKey } from '@/features/artifacts/artifacts-api.ts';
import { apiRequest } from '@/lib/api/client.ts';
import type { ApiRequestOptions } from '@/lib/api/api.types.ts';

/** Under the artifact's key, so it goes with the artifact's other queries. */
export const accessQueryKey = (artifactId: string) =>
  [...artifactQueryKey(artifactId), 'access'] as const;
export const userSearchQueryKey = (query: string) => ['user-search', query] as const;

const accessPath = (artifactId: string) => `/artifacts/${encodeURIComponent(artifactId)}/access`;

async function accessRequest(
  path: string,
  options: Omit<ApiRequestOptions<unknown>, 'schema'> = {},
): Promise<ArtifactAccess> {
  return (await apiRequest(path, { ...options, schema: artifactAccessResponseSchema })).access;
}

/** Owner only. */
export function fetchAccess(artifactId: string, signal?: AbortSignal): Promise<ArtifactAccess> {
  return accessRequest(accessPath(artifactId), { signal });
}

export function setCompanyAccess(
  artifactId: string,
  body: SetCompanyAccessRequest,
): Promise<ArtifactAccess> {
  return accessRequest(`${accessPath(artifactId)}/company`, { method: 'PUT', body });
}

/** Fails with `SHARE_RECIPIENT_UNKNOWN` (details: `unknownEmails`) if any email has no account. */
export function sharePeople(artifactId: string, body: SharePeopleRequest): Promise<ArtifactAccess> {
  return accessRequest(`${accessPath(artifactId)}/people`, { method: 'POST', body });
}

export function updatePerson(
  artifactId: string,
  userId: string,
  body: UpdatePersonAccessRequest,
): Promise<ArtifactAccess> {
  return accessRequest(`${accessPath(artifactId)}/people/${encodeURIComponent(userId)}`, {
    method: 'PATCH',
    body,
  });
}

export function removePerson(artifactId: string, userId: string): Promise<ArtifactAccess> {
  return accessRequest(`${accessPath(artifactId)}/people/${encodeURIComponent(userId)}`, {
    method: 'DELETE',
  });
}

/** Turns the link on, or changes its expiry or version (the URL stays the same). */
export function setShareLink(
  artifactId: string,
  body: SetShareLinkRequest,
): Promise<ArtifactAccess> {
  return accessRequest(`${accessPath(artifactId)}/link`, { method: 'PUT', body });
}

export function turnOffShareLink(artifactId: string): Promise<ArtifactAccess> {
  return accessRequest(`${accessPath(artifactId)}/link`, { method: 'DELETE' });
}

/** A new URL for the link; the old one stops working. */
export function resetShareLink(artifactId: string): Promise<ArtifactAccess> {
  return accessRequest(`${accessPath(artifactId)}/link/reset`, { method: 'POST' });
}

const sharedPath = (token: string) => `/s/${encodeURIComponent(token)}`;

export const sharedArtifactQueryKey = (token: string) => ['shared', token] as const;

/** What a share link shows. Needs no sign-in. */
export function fetchSharedArtifact(
  token: string,
  signal?: AbortSignal,
): Promise<SharedArtifactResponse> {
  return apiRequest(sharedPath(token), { schema: sharedArtifactResponseSchema, signal });
}

/** Where a share link's content is, relative to `/api`. */
export function sharedContentPath(token: string): string {
  return `${sharedPath(token)}/content`;
}

/** Other users whose email or name starts with `query` (3+ characters), at most five. */
export async function searchUsers(query: string, signal?: AbortSignal): Promise<UserSummary[]> {
  const params = new URLSearchParams({ q: query });
  return (await apiRequest(`/users/search?${params}`, { schema: userSearchResponseSchema, signal }))
    .items;
}
import {
  type ArtifactAccess,
  type SetCompanyAccessRequest,
  type SetShareLinkRequest,
  type SharePeopleRequest,
  type UpdatePersonAccessRequest,
  USER_SEARCH_MIN_LENGTH,
} from '@artifact-hub/shared';
import { keepPreviousData, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { artifactListsQueryKey, artifactQueryKey } from '@/features/artifacts/artifacts-api.ts';
import { useDebouncedValue } from '@/lib/use-debounced-value.ts';
import {
  accessQueryKey,
  fetchAccess,
  removePerson,
  searchUsers,
  fetchSharedArtifact,
  resetShareLink,
  setCompanyAccess,
  setShareLink,
  sharedArtifactQueryKey,
  sharePeople,
  turnOffShareLink,
  updatePerson,
  userSearchQueryKey,
} from './sharing-api.ts';

export function useAccess(artifactId: string, { enabled = true } = {}) {
  return useQuery({
    queryKey: accessQueryKey(artifactId),
    queryFn: ({ signal }) => fetchAccess(artifactId, signal),
    enabled,
  });
}

/**
 * Every change returns the access as it is now. Caches it, and refreshes the artifact (its
 * visibility) and the lists it appears in.
 */
function useAccessChange<T>(artifactId: string, change: (input: T) => Promise<ArtifactAccess>) {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: change,
    onSuccess: (access) => {
      queryClient.setQueryData(accessQueryKey(artifactId), access);
      void queryClient.invalidateQueries({ queryKey: artifactQueryKey(artifactId), exact: true });
      void queryClient.invalidateQueries({ queryKey: artifactListsQueryKey });
    },
  });
}

export function useSetCompanyAccess(artifactId: string) {
  return useAccessChange(artifactId, (body: SetCompanyAccessRequest) =>
    setCompanyAccess(artifactId, body),
  );
}

export function useSharePeople(artifactId: string) {
  return useAccessChange(artifactId, (body: SharePeopleRequest) => sharePeople(artifactId, body));
}

export function useUpdatePerson(artifactId: string) {
  return useAccessChange(
    artifactId,
    ({ userId, ...body }: UpdatePersonAccessRequest & { userId: string }) =>
      updatePerson(artifactId, userId, body),
  );
}

export function useRemovePerson(artifactId: string) {
  return useAccessChange(artifactId, (userId: string) => removePerson(artifactId, userId));
}

export function useSetShareLink(artifactId: string) {
  return useAccessChange(artifactId, (body: SetShareLinkRequest) => setShareLink(artifactId, body));
}

export function useTurnOffShareLink(artifactId: string) {
  return useAccessChange(artifactId, () => turnOffShareLink(artifactId));
}

export function useResetShareLink(artifactId: string) {
  return useAccessChange(artifactId, () => resetShareLink(artifactId));
}

/** What a share link shows; a link that doesn't work won't start working on a retry. */
export function useSharedArtifact(token: string) {
  return useQuery({
    queryKey: sharedArtifactQueryKey(token),
    queryFn: ({ signal }) => fetchSharedArtifact(token, signal),
    retry: false,
  });
}

/** Suggestions for the people picker, once the user pauses typing 3+ characters. */
export function useUserSearch(query: string) {
  const debounced = useDebouncedValue(query.trim(), 250);
  return useQuery({
    queryKey: userSearchQueryKey(debounced),
    queryFn: ({ signal }) => searchUsers(debounced, signal),
    enabled: debounced.length >= USER_SEARCH_MIN_LENGTH,
    placeholderData: keepPreviousData,
    staleTime: 60_000,
  });
}
import { toast } from 'sonner';
import { describeError } from '@/lib/api/api-error.ts';

/** Shows a failed action as a toast, for changes made outside a form. */
export function toastError(error: unknown): void {
  toast.error(describeError(error));
}
import { apiErrorBodySchema, ErrorCode } from '@artifact-hub/shared';
import { ApiError } from './api-error.ts';
import type { ApiRequestOptions } from './api.types.ts';

const NETWORK_ERROR_MESSAGE = "Can't reach the server. Check your connection and try again.";
const UNEXPECTED_RESPONSE_MESSAGE = 'The server sent an unexpected response. Please try again.';

/**
 * Calls the API on the same origin with the session cookie. Throws `ApiError` for error
 * responses and network failures, and validates success bodies with `schema`. A `FormData`
 * body is sent as multipart (the browser sets the boundary); anything else as JSON.
 */
export async function apiRequest<T = void>(
  path: string,
  { method = 'GET', body, schema, signal }: ApiRequestOptions<T> = {},
): Promise<T> {
  const isJson = body !== undefined && !(body instanceof FormData);
  const res = await send(path, {
    method,
    signal,
    headers: {
      Accept: 'application/json',
      ...(isJson ? { 'Content-Type': 'application/json' } : {}),
    },
    body: isJson ? JSON.stringify(body) : (body as FormData | undefined),
  });

  const payload: unknown = res.status === 204 ? undefined : await res.json().catch(() => undefined);
  if (!res.ok) throw toApiError(res.status, payload);

  if (!schema) return undefined as T;
  const parsed = schema.safeParse(payload);
  if (!parsed.success) {
    throw new ApiError(res.status, ErrorCode.INTERNAL_ERROR, UNEXPECTED_RESPONSE_MESSAGE);
  }
  return parsed.data;
}

/**
 * Fetches non-JSON content (artifact bytes) from the API, with the same error handling as
 * `apiRequest`. Returns the successful response for the caller to read.
 */
export async function apiFetchContent(
  path: string,
  { signal }: { signal?: AbortSignal } = {},
): Promise<Response> {
  const res = await send(path, { signal });
  if (!res.ok) throw toApiError(res.status, await res.json().catch(() => undefined));
  return res;
}

async function send(path: string, init: RequestInit): Promise<Response> {
  try {
    return await fetch(`/api${path}`, { ...init, credentials: 'same-origin' });
  } catch (error) {
    if (init.signal?.aborted) throw error;
    throw new ApiError(0, 'NETWORK_ERROR', NETWORK_ERROR_MESSAGE);
  }
}

function toApiError(status: number, payload: unknown): ApiError {
  const parsed = apiErrorBodySchema.safeParse(payload);
  if (!parsed.success) {
    return new ApiError(status, ErrorCode.INTERNAL_ERROR, UNEXPECTED_RESPONSE_MESSAGE);
  }
  const { code, message, details, requestId } = parsed.data.error;
  return new ApiError(status, code, message, details, requestId);
}
const relative = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });
const absolute = new Intl.DateTimeFormat('en', { dateStyle: 'medium' });

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** "just now", "5 minutes ago", "yesterday", "3 days ago"; a date after a week. */
export function formatRelativeTime(date: Date | string, now: Date = new Date()): string {
  const then = typeof date === 'string' ? new Date(date) : date;
  const elapsed = now.getTime() - then.getTime();
  if (elapsed < MINUTE) return 'just now';
  if (elapsed < HOUR) return relative.format(-Math.floor(elapsed / MINUTE), 'minute');
  if (elapsed < DAY) return relative.format(-Math.floor(elapsed / HOUR), 'hour');
  if (elapsed < 7 * DAY) return relative.format(-Math.floor(elapsed / DAY), 'day');
  return absolute.format(then);
}

/** "in 5 minutes", "in 3 hours", "tomorrow", "in 6 days"; "on <date>" after a week. */
export function formatTimeUntil(date: Date | string, now: Date = new Date()): string {
  const then = typeof date === 'string' ? new Date(date) : date;
  const remaining = then.getTime() - now.getTime();
  // Compare rounded values, so 23h59m reads "tomorrow" rather than "in 24 hours".
  const minutes = Math.max(1, Math.ceil(remaining / MINUTE));
  if (minutes < 60) return relative.format(minutes, 'minute');
  const hours = Math.round(remaining / HOUR);
  if (hours < 24) return relative.format(hours, 'hour');
  const days = Math.round(remaining / DAY);
  if (days <= 7) return relative.format(days, 'day');
  return `on ${absolute.format(then)}`;
}
import { Loader2Icon } from 'lucide-react';
import { Button } from '@/components/ui/button.tsx';
import { describeError } from '@/lib/api/api-error.ts';

/** A spinner that fills its container (a viewer, a list), unlike the full-page `PageLoading`. */
export function InlineLoading() {
  return (
    <div className="flex size-full items-center justify-center" aria-busy="true">
      <Loader2Icon className="size-6 animate-spin text-muted-foreground" aria-label="Loading" />
    </div>
  );
}

/** An error message with an optional retry, filling its container. */
export function InlineError({ error, onRetry }: { error: unknown; onRetry?: () => void }) {
  return (
    <div className="flex size-full flex-col items-center justify-center gap-3 p-6 text-center">
      <p role="alert" className="max-w-md text-sm text-muted-foreground">
        {typeof error === 'string' ? error : describeError(error)}
      </p>
      {onRetry ? (
        <Button variant="outline" size="sm" onClick={onRetry}>
          Try again
        </Button>
      ) : null}
    </div>
  );
}

