import type { Artifact } from '@artifact-hub/shared';
import { zodResolver } from '@hookform/resolvers/zod';
import { PencilIcon, Trash2Icon } from 'lucide-react';
import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { toast } from 'sonner';
import { FormError, TextAreaField, TextField } from '@/components/form-fields.tsx';
import { Badge } from '@/components/ui/badge.tsx';
import { Button } from '@/components/ui/button.tsx';
import { applyServerError } from '@/lib/forms/apply-server-error.ts';
import type { MetadataFormOutput, MetadataFormValues } from './artifacts.types.ts';
import { DeleteArtifactDialog } from './delete-artifact-dialog.tsx';
import { metadataFormSchema } from './metadata-form-schema.ts';
import { useUpdateArtifact } from './use-artifacts.ts';

/** The Details tab: description, tags and dates; the owner can edit them or delete the artifact. */
export function ArtifactDetails({ artifact }: { artifact: Artifact }) {
  const [editing, setEditing] = useState(false);

  if (editing) {
    return <DetailsForm artifact={artifact} onDone={() => setEditing(false)} />;
  }
  return (
    <div className="grid gap-4 text-sm">
      {artifact.description ? (
        <p className="break-words whitespace-pre-line">{artifact.description}</p>
      ) : (
        <p className="text-muted-foreground">No description.</p>
      )}
      {artifact.tags.length > 0 ? (
        <ul className="flex flex-wrap gap-1.5" aria-label="Tags">
          {artifact.tags.map((tag) => (
            <li key={tag}>
              <Badge variant="outline">{tag}</Badge>
            </li>
          ))}
        </ul>
      ) : null}
      <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-muted-foreground">
        <dt>Created</dt>
        <dd className="text-foreground">{new Date(artifact.createdAt).toLocaleString()}</dd>
      </dl>
      {artifact.permissions.edit || artifact.permissions.delete ? (
        <div className="flex flex-wrap gap-2">
          {artifact.permissions.edit ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(true)}>
              <PencilIcon aria-hidden="true" />
              Edit details
            </Button>
          ) : null}
          {artifact.permissions.delete ? (
            <DeleteArtifactDialog artifact={artifact}>
              <Button variant="outline" size="sm" className="text-destructive">
                <Trash2Icon aria-hidden="true" />
                Delete
              </Button>
            </DeleteArtifactDialog>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

/** Edits the title, description and tags. Saving never creates a version. */
function DetailsForm({ artifact, onDone }: { artifact: Artifact; onDone: () => void }) {
  const update = useUpdateArtifact(artifact.id);
  const {
    register,
    handleSubmit,
    setError,
    formState: { errors, isSubmitting },
  } = useForm<MetadataFormValues, unknown, MetadataFormOutput>({
    resolver: zodResolver(metadataFormSchema),
    defaultValues: {
      title: artifact.title,
      description: artifact.description,
      tags: artifact.tags.join(', '),
    },
  });

  const submit = handleSubmit(async (changes) => {
    try {
      await update.mutateAsync(changes);
      toast.success('Details saved');
      onDone();
    } catch (error) {
      applyServerError(error, setError, ['title', 'description', 'tags']);
    }
  });

  return (
    <form noValidate className="grid gap-4" onSubmit={(event) => void submit(event)}>
      <FormError message={errors.root?.server?.message} />
      <TextField label="Title" error={errors.title?.message} {...register('title')} />
      <TextAreaField
        label="Description"
        rows={4}
        error={errors.description?.message}
        {...register('description')}
      />
      <TextField
        label="Tags"
        hint="Separate tags with commas"
        error={errors.tags?.message}
        {...register('tags')}
      />
      <div className="flex justify-end gap-2">
        <Button type="button" variant="outline" disabled={isSubmitting} onClick={onDone}>
          Cancel
        </Button>
        <Button type="submit" disabled={isSubmitting}>
          {isSubmitting ? 'Saving…' : 'Save'}
        </Button>
      </div>
    </form>
  );
}
import type { SharedPerson } from '@artifact-hub/shared';
import { XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button.tsx';
import { toastError } from '@/lib/toast-error.ts';
import { PermissionSelect, VersionSelect } from './access-selects.tsx';
import { useRemovePerson, useUpdatePerson } from './use-sharing.ts';

/** Everyone the artifact is shared with; changes are saved as they are made. */
export function PeopleList({ artifactId, people }: { artifactId: string; people: SharedPerson[] }) {
  const update = useUpdatePerson(artifactId);
  const remove = useRemovePerson(artifactId);

  if (people.length === 0) {
    return <p className="text-sm text-muted-foreground">Not shared with anyone yet.</p>;
  }

  return (
    <ul className="grid gap-1" aria-label="People with access">
      {people.map((person) => {
        const { user } = person;
        const busy =
          (update.isPending && update.variables.userId === user.id) ||
          (remove.isPending && remove.variables === user.id);
        return (
          <li key={user.id} className="flex flex-wrap items-center gap-2 py-1.5 text-sm">
            <span className="grid min-w-0 flex-1 basis-40">
              <span className="truncate font-medium">{user.displayName}</span>
              <span className="truncate text-xs text-muted-foreground">{user.email}</span>
            </span>
            <PermissionSelect
              aria-label={`Permission for ${user.displayName}`}
              value={person.permission}
              disabled={busy}
              onChange={(permission) =>
                update.mutate({ userId: user.id, permission }, { onError: toastError })
              }
            />
            <VersionSelect
              aria-label={`Version for ${user.displayName}`}
              artifactId={artifactId}
              value={person.pinnedVersionNo}
              disabled={busy}
              onChange={(versionNo) =>
                update.mutate({ userId: user.id, versionNo }, { onError: toastError })
              }
            />
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label={`Remove ${user.displayName}`}
              disabled={busy}
              onClick={() => remove.mutate(user.id, { onError: toastError })}
            >
              <XIcon aria-hidden="true" />
            </Button>
          </li>
        );
      })}
    </ul>
  );
}
import * as React from 'react';
import { cn } from '@/lib/utils';

function Textarea({ className, ...props }: React.ComponentProps<'textarea'>) {
  return (
    <textarea
      data-slot="textarea"
      className={cn(
        'flex field-sizing-content min-h-16 w-full rounded-md border border-input bg-transparent px-3 py-2 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 md:text-sm dark:bg-input/30 dark:aria-invalid:ring-destructive/40',
        className,
      )}
      {...props}
    />
  );
}

export { Textarea };
import type { Artifact } from '@artifact-hub/shared';
import type { ReactNode } from 'react';
import { useNavigate } from 'react-router';
import { toast } from 'sonner';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog.tsx';
import { buttonVariants } from '@/components/ui/button.tsx';
import { describeError } from '@/lib/api/api-error.ts';
import { useDeleteArtifact } from './use-artifacts.ts';

/** Asks before deleting `artifact`, then goes home. Opened from `children` (the trigger). */
export function DeleteArtifactDialog({
  artifact,
  children,
}: {
  artifact: Artifact;
  children: ReactNode;
}) {
  const navigate = useNavigate();
  const remove = useDeleteArtifact(artifact.id, () => navigate('/', { replace: true }));

  const confirm = () =>
    remove.mutate(undefined, {
      onSuccess: () => toast.success(`Deleted “${artifact.title}”`),
      onError: (error) => toast.error(describeError(error)),
    });

  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>{children}</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          <AlertDialogTitle>Delete “{artifact.title}”?</AlertDialogTitle>
          <AlertDialogDescription>
            All its versions are removed for everyone it was shared with, and its links stop
            working.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction
            className={buttonVariants({ variant: 'destructive' })}
            disabled={remove.isPending}
            onClick={confirm}
          >
            Delete
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
