import { type ComponentProps, type ReactNode, useId } from 'react';
import { Input } from '@/components/ui/input.tsx';
import { Label } from '@/components/ui/label.tsx';
import { NativeSelect } from '@/components/ui/native-select.tsx';
import { Textarea } from '@/components/ui/textarea.tsx';

interface FieldProps {
  label: string;
  hint?: string;
  error?: string;
}

/** Ids and ARIA props that tie a control to its hint and error message. */
function useFieldIds(id: string | undefined, { hint, error }: FieldProps) {
  const generatedId = useId();
  const controlId = id ?? generatedId;
  const hintId = `${controlId}-hint`;
  const errorId = `${controlId}-error`;
  const describedBy = [error ? errorId : null, hint ? hintId : null].filter(Boolean).join(' ');
  return {
    controlId,
    hintId,
    errorId,
    controlProps: {
      id: controlId,
      'aria-invalid': error ? true : undefined,
      'aria-describedby': describedBy || undefined,
    },
  };
}

function Field({
  label,
  hint,
  error,
  ids,
  children,
}: FieldProps & { ids: ReturnType<typeof useFieldIds>; children: ReactNode }) {
  return (
    <div className="grid gap-2">
      <Label htmlFor={ids.controlId}>{label}</Label>
      {children}
      {error ? (
        <p id={ids.errorId} className="text-sm text-destructive">
          {error}
        </p>
      ) : hint ? (
        <p id={ids.hintId} className="text-sm text-muted-foreground">
          {hint}
        </p>
      ) : null}
    </div>
  );
}

/** A labelled input with an optional hint and an error message wired up for screen readers. */
export function TextField({
  label,
  hint,
  error,
  id,
  ...inputProps
}: FieldProps & ComponentProps<typeof Input>) {
  const ids = useFieldIds(id, { label, hint, error });
  return (
    <Field label={label} hint={hint} error={error} ids={ids}>
      <Input {...ids.controlProps} {...inputProps} />
    </Field>
  );
}

/** `TextField` for multi-line text. */
export function TextAreaField({
  label,
  hint,
  error,
  id,
  ...textareaProps
}: FieldProps & ComponentProps<typeof Textarea>) {
  const ids = useFieldIds(id, { label, hint, error });
  return (
    <Field label={label} hint={hint} error={error} ids={ids}>
      <Textarea {...ids.controlProps} {...textareaProps} />
    </Field>
  );
}

/** `TextField` for a choice from a short list; pass `<option>`s as children. */
export function SelectField({
  label,
  hint,
  error,
  id,
  ...selectProps
}: FieldProps & ComponentProps<typeof NativeSelect>) {
  const ids = useFieldIds(id, { label, hint, error });
  return (
    <Field label={label} hint={hint} error={error} ids={ids}>
      <NativeSelect {...ids.controlProps} {...selectProps} />
    </Field>
  );
}

/** A form-level error (e.g. wrong credentials), announced when it appears. */
export function FormError({ message }: { message?: string }) {
  if (!message) return null;
  return (
    <p
      role="alert"
      className="rounded-md border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive"
    >
      {message}
    </p>
  );
}
import type { FieldValues, Path, UseFormSetError } from 'react-hook-form';
import { describeError, isApiError } from '@/lib/api/api-error.ts';

/**
 * Shows a failed submission on the form: validation issues next to their fields, everything
 * else as a form-level message (`errors.root.server`). An issue on a nested path (`tags.0`)
 * goes to the field it belongs to (`tags`).
 */
export function applyServerError<T extends FieldValues>(
  error: unknown,
  setError: UseFormSetError<T>,
  fields: readonly Path<T>[],
): void {
  if (isApiError(error)) {
    let applied = false;
    for (const issue of error.fieldIssues) {
      const field = fields.find((f) => issue.path === f || issue.path.startsWith(`${f}.`));
      if (!field) continue;
      setError(field, { message: issue.message });
      applied = true;
    }
    if (applied) return;
  }
  setError('root.server', { message: describeError(error) });
}
import { ErrorCode } from '@artifact-hub/shared';
import type { ClientErrorCode, FieldIssue } from './api.types.ts';

/** An error returned by the API (`{ error: { code, message, details?, requestId? } }`) or a network failure. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: ClientErrorCode,
    message: string,
    readonly details?: unknown,
    readonly requestId?: string,
  ) {
    super(message);
    this.name = 'ApiError';
  }

  /** Per-field messages of a `VALIDATION_FAILED` error. */
  get fieldIssues(): FieldIssue[] {
    if (this.code !== ErrorCode.VALIDATION_FAILED || !Array.isArray(this.details)) return [];
    return this.details.filter(
      (issue): issue is FieldIssue =>
        typeof issue?.path === 'string' && typeof issue?.message === 'string',
    );
  }

  /** Worth retrying: the server was unreachable or failed, not the request itself. */
  get isTransient(): boolean {
    return this.code === 'NETWORK_ERROR' || this.status >= 500;
  }
}

export function isApiError(error: unknown, code?: ClientErrorCode): error is ApiError {
  return error instanceof ApiError && (code === undefined || error.code === code);
}

/** A user-facing message, with the request ID for server failures so it can be reported. */
export function describeError(error: unknown): string {
  if (!isApiError(error)) return 'Something went wrong. Please try again.';
  if (error.status >= 500 && error.requestId) {
    return `${error.message} (request ID: ${error.requestId})`;
  }
  return error.message;
}
