/** A run of plain text, or a web link found in it. */
export type TextPart = { type: 'text'; text: string } | { type: 'link'; text: string; href: string };

/** `http(s)://` up to the next space; never other schemes, so `javascript:` stays text. */
const URL_PATTERN = /\bhttps?:\/\/[^\s<>"]+/gi;
/** Punctuation that usually ends the sentence rather than the URL. */
const TRAILING_PUNCTUATION = /[.,;:!?'")\]}]+$/;

/**
 * Splits user-written text into plain text and `http(s)` links, for rendering links in
 * comments without ever rendering the text as HTML. Unbalanced closing brackets and trailing
 * punctuation are left out of a link (`(see https://x.io/a).` links `https://x.io/a`).
 */
export function splitLinks(text: string): TextPart[] {
  const parts: TextPart[] = [];
  let rest = 0;
  for (const match of text.matchAll(URL_PATTERN)) {
    const href = trimUrl(match[0]);
    const start = match.index;
    if (start > rest) parts.push({ type: 'text', text: text.slice(rest, start) });
    parts.push({ type: 'link', text: href, href });
    rest = start + href.length;
  }
  if (rest < text.length) parts.push({ type: 'text', text: text.slice(rest) });
  return mergeText(parts);
}

function trimUrl(url: string): string {
  let trimmed = url;
  for (;;) {
    const next = trimmed.replace(TRAILING_PUNCTUATION, (tail) => keepBalanced(trimmed, tail));
    if (next === trimmed) return trimmed;
    trimmed = next;
  }
}

/** The part of `tail` to keep: a closing bracket that closes one opened inside the URL. */
function keepBalanced(url: string, tail: string): string {
  const close = tail[0];
  const open = close === ')' ? '(' : close === ']' ? '[' : close === '}' ? '{' : null;
  if (!open) return '';
  const body = url.slice(0, url.length - tail.length);
  const opened = body.split(open).length - 1;
  const closed = body.split(close).length - 1;
  return opened > closed ? close : '';
}

/** Joins adjacent text parts left by trimming. */
function mergeText(parts: TextPart[]): TextPart[] {
  const merged: TextPart[] = [];
  for (const part of parts) {
    const last = merged.at(-1);
    if (part.type === 'text' && last?.type === 'text') last.text += part.text;
    else merged.push(part);
  }
  return merged;
}

