import type { Artifact, CommentThread as CommentThreadData } from '@artifact-hub/shared';
import { ChevronDownIcon, ChevronRightIcon } from 'lucide-react';
import { useState } from 'react';
import { Link } from 'react-router';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';
import { Badge } from '@/components/ui/badge.tsx';
import { Button } from '@/components/ui/button.tsx';
import { cn } from '@/lib/utils';
import { CommentForm } from './comment-form.tsx';
import { CommentThread } from './comment-thread.tsx';
import type { FeedbackFilter } from './comments.types.ts';
import { useCommentThreads, useCreateComment } from './use-comments.ts';

/**
 * The Feedback tab: the comments on the version being viewed (`versionNo`) or on every version,
 * open threads first and resolved ones folded away, with a box to add one for those who may
 * comment. `versionNo` is null when no version is shown; all comments are listed then.
 */
export function FeedbackPanel({
  artifact,
  versionNo,
}: {
  artifact: Artifact;
  versionNo: number | null;
}) {
  const [filter, setFilter] = useState<FeedbackFilter>('version');
  const [showResolved, setShowResolved] = useState(false);
  const shownVersionNo = filter === 'version' ? versionNo : null;
  const { data: threads, error, refetch, isPlaceholderData } = useCommentThreads(
    artifact.id,
    shownVersionNo,
  );
  const create = useCreateComment(artifact.id);
  const canComment = artifact.permissions.comment;

  return (
    <div className="grid gap-4">
      {versionNo !== null ? (
        <div role="group" aria-label="Show comments on" className="flex rounded-md border p-0.5">
          {(['version', 'all'] as const).map((option) => (
            <Button
              key={option}
              variant={filter === option ? 'secondary' : 'ghost'}
              size="xs"
              className="flex-1"
              aria-pressed={filter === option}
              onClick={() => setFilter(option)}
            >
              {option === 'version' ? `This version (v${versionNo})` : 'All versions'}
            </Button>
          ))}
        </div>
      ) : null}

      {canComment && versionNo !== null ? (
        <CommentForm
          label="Add a comment"
          placeholder={`Comment on v${versionNo}…`}
          submitLabel="Comment"
          onSubmit={(body) => create.mutateAsync({ body, versionNo })}
        />
      ) : !canComment ? (
        <p className="text-sm text-muted-foreground">You can read the comments, but not add any.</p>
      ) : null}

      {error && !threads ? (
        <InlineError error={error} onRetry={() => void refetch()} />
      ) : !threads ? (
        <div className="h-24">
          <InlineLoading />
        </div>
      ) : (
        <div className={cn('grid gap-3 transition-opacity', isPlaceholderData && 'opacity-60')}>
          <ThreadList
            artifact={artifact}
            threads={threads.filter((thread) => thread.resolvedAt === null)}
            showVersions={shownVersionNo === null}
            emptyText={
              threads.length > 0
                ? 'No open comments.'
                : shownVersionNo === null
                  ? 'No comments yet.'
                  : `No comments on v${shownVersionNo} yet.`
            }
            label="Open comments"
          />
          <ResolvedThreads
            artifact={artifact}
            threads={threads.filter((thread) => thread.resolvedAt !== null)}
            showVersions={shownVersionNo === null}
            open={showResolved}
            onToggle={() => setShowResolved((shown) => !shown)}
          />
        </div>
      )}
    </div>
  );
}

function ResolvedThreads({
  artifact,
  threads,
  showVersions,
  open,
  onToggle,
}: {
  artifact: Artifact;
  threads: CommentThreadData[];
  showVersions: boolean;
  open: boolean;
  onToggle: () => void;
}) {
  if (threads.length === 0) return null;
  const Chevron = open ? ChevronDownIcon : ChevronRightIcon;
  return (
    <>
      <Button
        variant="ghost"
        size="sm"
        className="justify-self-start text-muted-foreground"
        aria-expanded={open}
        onClick={onToggle}
      >
        <Chevron aria-hidden="true" />
        Resolved ({threads.length})
      </Button>
      {open ? (
        <ThreadList
          artifact={artifact}
          threads={threads}
          showVersions={showVersions}
          label="Resolved comments"
        />
      ) : null}
    </>
  );
}

function ThreadList({
  artifact,
  threads,
  showVersions,
  emptyText,
  label,
}: {
  artifact: Artifact;
  threads: CommentThreadData[];
  /** Label each thread with its version, linking to it. */
  showVersions: boolean;
  emptyText?: string;
  label: string;
}) {
  if (threads.length === 0) {
    return emptyText ? <p className="text-sm text-muted-foreground">{emptyText}</p> : null;
  }
  const currentVersionNo = artifact.currentVersion?.versionNo;
  return (
    <ol className="grid gap-3" aria-label={label}>
      {threads.map((thread) => (
        <CommentThread
          key={thread.id}
          artifactId={artifact.id}
          thread={thread}
          canReply={artifact.permissions.comment}
          badges={
            showVersions ? (
              <Badge asChild variant="outline">
                <Link
                  to={
                    thread.versionNo === currentVersionNo
                      ? `/artifacts/${artifact.id}`
                      : `/artifacts/${artifact.id}?v=${thread.versionNo}`
                  }
                  aria-label={`On version ${thread.versionNo}`}
                >
                  v{thread.versionNo}
                </Link>
              </Badge>
            ) : null
          }
        />
      ))}
    </ol>
  );
}
