content.content:
14	/**
15	 * The Feedback tab: a box to add a comment for those who may comment, then the comments on the
16	 * version being viewed (`versionNo`) or on every version, open threads first and resolved ones
17	 * folded away. `versionNo` is null when no version is shown; all comments are listed then.
18	 */
19	export function FeedbackPanel({
20	  artifact,
21	  versionNo,
22	}: {
23	  artifact: Artifact;
24	  versionNo: number | null;
25	}) {
26	  const [filter, setFilter] = useState<FeedbackFilter>('version');
27	  const [showResolved, setShowResolved] = useState(false);
28	  const shownVersionNo = filter === 'version' ? versionNo : null;
29	  const {
30	    data: threads,
31	    error,
32	    refetch,
33	    isPlaceholderData,
34	  } = useCommentThreads(artifact.id, shownVersionNo);
35	  const create = useCreateComment(artifact.id);
36	  const canComment = artifact.permissions.comment;
37	  const filterLabelId = useId();
38	
39	  return (
40	    <div className="grid gap-4">
41	      {canComment && versionNo !== null ? (
42	        <CommentForm
43	          label="Add a comment"
44	          placeholder={`Comment on v${versionNo}…`}
45	          submitLabel="Comment"
46	          onSubmit={(body) => create.mutateAsync({ body, versionNo })}
47	        />
48	      ) : !canComment ? (
49	        <p className="text-sm text-muted-foreground">You can read the comments, but not add any.</p>
50	      ) : null}
51	
52	      {versionNo !== null ? (
53	        <div className="grid gap-1.5">
54	          <span id={filterLabelId} className="text-xs font-medium text-muted-foreground">
55	            Show feedback for:
56	          </span>
57	          <div
58	            role="group"
59	            aria-labelledby={filterLabelId}
60	            className="flex rounded-md border p-0.5"
61	          >
62	            {(['version', 'all'] as const).map((option) => (
63	              <Button
64	                key={option}
65	                variant={filter === option ? 'secondary' : 'ghost'}
66	                size="xs"
67	                className="flex-1"
68	                aria-pressed={filter === option}
69	                onClick={() => setFilter(option)}
70	              >
71	                {option === 'version' ? `This version (v${versionNo})` : 'All versions'}
72	              </Button>
73	            ))}
74	          </div>
75	        </div>
76	      ) : null}
77	
78	      {error && !threads ? (
79	        <InlineError error={error} onRetry={() => void refetch()} />
80	      ) : !threads ? (
81	        <div className="h-24">
82	          <InlineLoading />
83	        </div>
84	      ) : (
85	        <div className={cn('grid gap-3 transition-opacity', isPlaceholderData && 'opacity-60')}>
86	          <ThreadList
87	            artifact={artifact}
88	            threads={threads.filter((thread) => thread.resolvedAt === null)}
89	            showVersions={shownVersionNo === null}
90	            emptyText={
91	              threads.length > 0
92	                ? 'No open comments.'
93	                : shownVersionNo === null
94	                  ? 'No comments yet.'
95	                  : `No comments on v${shownVersionNo} yet.`
96	            }
97	            label="Open comments"
98	          />
99	          <ResolvedThreads
100	            artifact={artifact}
101	            threads={threads.filter((thread) => thread.resolvedAt !== null)}
102	            showVersions={shownVersionNo === null}
103	            open={showResolved}
104	            onToggle={() => setShowResolved((shown) => !shown)}
105	          />
106	        </div>
107	      )}
108	    </div>
109	  );
110	}
111	
112	function ResolvedThreads({
113	  artifact,
114	  threads,
115	  showVersions,
116	  open,
117	  onToggle,
118	}: {
119	  artifact: Artifact;
120	  threads: CommentThreadData[];
121	  showVersions: boolean;
122	  open: boolean;
123	  onToggle: () => void;
124	}) {
125	  if (threads.length === 0) return null;
126	  const Chevron = open ? ChevronDownIcon : ChevronRightIcon;
127	  return (
128	    <>
129	      <Button
130	        variant="ghost"
131	        size="sm"
132	        className="justify-self-start text-muted-foreground"
133	        aria-expanded={open}
134	        onClick={onToggle}
135	      >
136	        <Chevron aria-hidden="true" />
137	        Resolved ({threads.length})
138	      </Button>
139	      {open ? (
140	        <ThreadList
141	          artifact={artifact}
142	          threads={threads}
143	          showVersions={showVersions}
144	          label="Resolved comments"
145	        />
146	      ) : null}
147	    </>
148	  );
149	}
150	
151	function ThreadList({
152	  artifact,
153	  threads,
154	  showVersions,
155	  emptyText,
156	  label,
157	}: {
158	  artifact: Artifact;
159	  threads: CommentThreadData[];
160	  /** Label each thread with its version, linking to it. */
161	  showVersions: boolean;
162	  emptyText?: string;
163	  label: string;
164	}) {
165	  if (threads.length === 0) {
166	    return emptyText ? <p className="text-sm text-muted-foreground">{emptyText}</p> : null;
167	  }
168	  const currentVersionNo = artifact.currentVersion?.versionNo;
169	  return (
170	    <ol className="grid gap-3" aria-label={label}>
171	      {threads.map((thread) => (
172	        <CommentThread
173	          key={thread.id}
174	          artifactId={artifact.id}
175	          thread={thread}
176	          canReply={artifact.permissions.comment}
177	          badges={
178	            showVersions ? (
179	              <Badge asChild variant="outline">
180	                <Link
181	                  to={
182	                    thread.versionNo === currentVersionNo
183	                      ? `/artifacts/${artifact.id}`
184	                      : `/artifacts/${artifact.id}?v=${thread.versionNo}`
185	                  }
186	                  aria-label={`On version ${thread.versionNo}`}
187	                >
188	                  v{thread.versionNo}
189	                </Link>
190	              </Badge>
191	            ) : null
192	          }
193	        />
194	      ))}
195	    </ol>
196	  );
197	}
